(* [comment removed for export] *)
Lemma ud_S4 : forall (fx : FPState) regs m (s : Z),
  (240 <= s)%Z ->
  (s < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 200)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 240) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b53c : word) m rom) (@mkst fx regs' (0x93934 : word) (wr8w m (s - 200) (getr regs 10)) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b558
    /\ getr regs' 10 = getr regs 19
    /\ getr regs' 11 = Z_to_bv 64 0x17f47
    /\ getr regs' 12 = Z_to_bv 64 0
    /\ getr regs' 22 = getr regs 10
