(* [comment removed for export] *)
Lemma ud_B1e : forall (fx : FPState) regs m (s : Z),
  (240 <= s)%Z ->
  (s < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 160)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 240) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b778 : word) m rom) (@mkst fx regs' (0x78fb8 : word) (wr8w m (s - 160) (getr regs 10)) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b788
    /\ getr regs' 10 = getr regs 10
    /\ getr regs' 11 = Z_to_bv 64 (s - 124)
    /\ getr regs' 12 = Z_to_bv 64 0
    /\ regs_agree (fun r => In r [1; 11; 12]%list) regs regs'.
