Lemma ud_B2b : forall (fx : FPState) regs m (s : Z),
  (240 <= s)%Z ->
  (s < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 144)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 240) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b7c8 : word) m rom) (@mkst fx regs' (0x8fb4c : word) (wr8w m (s - 144) (getr regs 10)) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b7dc
    /\ getr regs' 10 = Z_to_bv 64 0
    /\ getr regs' 11 = getr regs 23
    /\ getr regs' 12 = getr regs 22
