(* [comment removed for export] *)
Lemma ud_B2c : forall (fx : FPState) regs m (s : Z) (p1 : word),
  (240 <= s)%Z ->
  (s < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 144)) 8 = Some (word_to_le_bytes 8 p1) ->
  store_ok SEGS m (Z_to_bv 64 (s - 152)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 240) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b7dc : word) m rom) (@mkst fx regs' (0x78e14 : word) (wr8w m (s - 152) (getr regs 10)) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b7f0
    /\ getr regs' 10 = p1
    /\ getr regs' 11 = p1
    /\ getr regs' 12 = getr regs 10
    /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs'.
Proof.
