(* [comment removed for export] *)
Lemma ud_F : forall fr cs regs m (s pconf : Z) (b0 b1 : list byte),
  (240 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pconf)%Z -> (pconf + 4 <= 2 ^ 64)%Z -> frm_zero cs ->
  rdn SEGS m (Z_to_bv 64 (s - 124)) 4 = Some b0 -> length b0 = 4%nat ->
  rdn SEGS m (Z_to_bv 64 (s - 128)) 4 = Some b1 -> length b1 = 4%nat ->
  store_ok SEGS m (Z_to_bv 64 pconf) 4 = true ->
  getr regs 2 = Z_to_bv 64 (s - 240) -> getr regs 8 = Z_to_bv 64 pconf -> getr regs 9 = Z_to_bv 64 0 -> getr regs 18 = Z_to_bv 64 70 ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x9b85c : word) m rom)
    (fun fin => exists fr' cs' regs' (M' : word -> option byte),
       fin = @mkst (mkFP fr' cs') regs' (0x6cb3c : word) M' rom /\ frm_zero cs' /\
       (M' = m \/ exists y, (0 <= y < 2 ^ 32)%Z /\ M' = wbytes m (Z_to_bv 64 pconf) (Z_to_le_bytes 4 y)) /\
       getr regs' 1 = Z_to_bv 64 0x9b92c /\ getr regs' 10 = Z_to_bv 64 (s - 136) /\
       regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs').
