(* [comment removed for export] *)
Lemma ud_T1 : forall (fx : FPState) regs m (s : Z),
  (240 <= s)%Z ->
  (s < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 240) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b92c : word) m rom) (@mkst fx regs' (0x6cb3c : word) (m) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b934
    /\ getr regs' 10 = Z_to_bv 64 (s - 168)
    /\ regs_agree (fun r => In r [1; 10]%list) regs regs'.
Proof.
