(* [comment removed for export] *)
Lemma ud_T2 : forall (fx : FPState) regs m (s : Z),
  (240 <= s)%Z ->
  (s < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 240) ->
  exists regs',
    msteps SEGS (@mkst fx regs (0x9b934 : word) m rom) (@mkst fx regs' (0x923f0 : word) (m) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x9b93c
    /\ getr regs' 10 = Z_to_bv 64 (s - 176)
